import sys
sys.path.insert(0, '/testbed')
from exceptiongroup import ExceptionGroup

def raise_excgroup():
    exceptions = []
    try:
        raise ValueError('foo')
    except ValueError as exc:
        exceptions.append(exc)

    try:
        raise RuntimeError('bar')
    except RuntimeError as exc:
        exc.__notes__ = ['Note from bar handler']
        exceptions.append(exc)

    exc = ExceptionGroup('test message', exceptions)
    exc.add_note('Displays notes attached to the group too')
    raise exc

try:
    raise_excgroup()
except ExceptionGroup as exc:
    import traceback
    for frame, lineno in traceback.walk_tb(exc.__traceback__):
        print(f'Frame: {frame.f_code.co_filename}:{lineno} in {frame.f_code.co_name}')
        print(f'  f_lineno: {frame.f_lineno}')
"

